RDN1","Manufacturer reference: https://www.midea.com/ng/air-conditioners/floor-standing-aircons/r410-inverter-floor-standing-air-conditioner-pa-series.mfpa-18crdni"],"image":"/assets/products/models/midea-mfpa18crdn1.jpg","sort":212},{"slug":"midea-mcd24hrdn1-cassette-ac","name":"Midea MCD-24HRDN1 2.5HP Ceiling-Cassette AC","category":"air-conditioners","brand":"Midea","description":"A ceiling-mounted cassette AC example for a recessed installation. Confirm the Nigerian variant, ceiling clearance, electrical supply and installer requirements with the store.","specs":["2.5HP manufacturer capacity class","Ceiling-cassette air conditioner","Independent vane control","Built-in drain pump","Model: MCD-24HRDN1","Manufacturer reference: https://www.midea.com/ma/air-conditioners/cassette/midea-mcdx-series-ceiling-cassette-air-conditioner-2-5hp.mcd-24hrdn1"],"image":"/assets/products/models/midea-mcd24hrdn1.jpg","sort":213}]$models$::jsonb)
  as m(slug text, name text, category text, brand text, description text, specs jsonb, image text, sort integer)
)
insert into public.products (slug, name, category_id, brand_name, description, specs, image_url, featured, active, sort_order)
select m.slug, m.name, c.id, m.brand, m.description,
  array(select jsonb_array_elements_text(m.specs)), m.image, false, true, m.sort
from models m join public.categories c on c.id = m.category
on conflict (slug) do nothing
returning slug;
